import {aggregate,clock as nyClock} from './engine.mjs';
import {summarize} from './comparison-engine.mjs';
const cache=new Map();const clock=t=>{if(!cache.has(t))cache.set(t,nyClock(t));return cache.get(t);};
export const timeConfig={version:'time-study-1',timeframes:[1,3,5],windows:[{id:'morning',name:'Morning',start:'09:45',end:'11:30'},{id:'midday',name:'Midday',start:'11:30',end:'14:00'},{id:'afternoon',name:'Afternoon',start:'14:00',end:'15:30'}],developmentDays:['2026-10-22','2026-10-23','2026-10-26','2026-10-27','2026-10-28','2026-10-29','2026-11-02','2026-11-03','2026-11-04','2026-11-05','2026-11-06'],checkDays:['2026-11-09','2026-11-10','2026-11-11','2026-11-12','2026-11-13'],freshDays:['2026-11-12','2026-11-13'],risk:100,maxContracts:3,dailyLoss:300,commission:1.24,slipTicks:1,rr:2,minGap:1,buffer:1,atrPeriod:14,gapLifeBars:10,sweepLookback:20,structureLookback:5,structureDeadline:5,pivotConfirmBars:2,minimumDevelopmentTrades:10};
export const timeModels=[
{id:'orb',name:'ORB',fullName:'15-minute opening range breakout',rules:'Freeze 09:30–09:44 New York. First chart close ≥ 1 point outside this range; one attempt per day, next-minute-open entry. Stop one chart ATR(14) from signal close. Later windows can have no trades because the first daily break has already happened.'},
{id:'fvg',name:'FVG',fullName:'Directional gap retest',rules:'Three contiguous chart candles form a wick gap ≥ 1 point, with the middle body ≥ 0.5 ATR(14) in the gap direction. Within 10 chart bars, require a later touch and a directional candle closing beyond the gap midpoint. Stop beyond the far gap edge by 1 point. A close through that edge invalidates the original gap.'},
{id:'ifvg',name:'IFVG',fullName:'Inverse fair value gap',rules:'The same three-candle gap definition. Within 10 chart bars, a completed close through the opposite edge triggers inversion. Trade in the new direction, with the stop beyond the inversion candle and original gap by 1 point. This tests immediate close-confirmation, not a later inverse-gap retest.'},
{id:'ict',name:'ICT-style',fullName:'Sweep → structure shift → FVG retest',rules:'An analyst-defined subset, not all ICT teachings. Sweep and reclaim the previous 20 chart-bar high/low by ≥ 0.25 point. Within 5 bars, a directional candle with body ≥ ATR(14) must close through the opposite 5-bar structure level frozen before the sweep. A same-direction FVG then forms and is retested within 10 bars, with directional close beyond its midpoint. Stop beyond the sweep extreme by 1 point.'},
{id:'hs',name:'Head & shoulders',fullName:'Confirmed-pivot neckline breakout',rules:'Use alternating strict high/low pivots confirmed only after 2 bars on each side. Last 5 pivots must form H-L-H-L-H (or inverse), total span ≤ 40 bars, head ≥ 0.5 ATR beyond both shoulders and shoulders within 1 ATR. Project the neckline through the intervening pivots; require a completed close ≥ 0.25 point through it after right-shoulder confirmation. Stop beyond the right shoulder by 1 point. One attempt per pattern.'},
{id:'liquidity',name:'Liquidity sweep',fullName:'Prior-range sweep and reclaim',rules:'Price sweeps the previous 20 chart-bar high or low by ≥ 0.25 point and closes back inside the prior range. Enter next minute in the reclaim direction. A candle sweeping both sides is ambiguous and skipped. Stop beyond its extreme by 1 point. This is a price-only sweep proxy, not proof of stop orders or institutional intent.'}
];
const tick=x=>Math.round(x*4)/4,up=x=>Math.ceil(x*4-1e-8)/4,down=x=>Math.floor(x*4+1e-8)/4;
export function chartBars(minutes,tf){if(tf===1)return minutes.map(b=>({...b,end:b.t+60000}));return aggregate(minutes,tf);}
export function detectSetups(minutes,tf,model,cfg=timeConfig){const bs=chartBars(minutes,tf),features=[],signals=[],gaps=[],pivots=[],usedPatterns=new Set();let orbUsed=false,sweep=null;const opening=minutes.filter(b=>{const h=clock(b.t).hm;return h>='09:30'&&h<'09:45';}),orHigh=Math.max(...opening.map(b=>b.h)),orLow=Math.min(...opening.map(b=>b.l));
function push(b,i,c){signals.push({model,timeframe:tf,day:clock(b.t).day,signalTime:b.t,confirmedAt:b.end,chartIndex:i,status:'Detected',...c});}
for(let i=0;i<bs.length;i++){const b=bs[i],prev=bs[i-1];const tr=Math.max(b.h-b.l,prev?Math.abs(b.h-prev.c):0,prev?Math.abs(b.l-prev.c):0);features.push({tr,atr:null});if(i>=cfg.atrPeriod-1)features[i].atr=features.slice(i-cfg.atrPeriod+1,i+1).reduce((s,x)=>s+x.tr,0)/cfg.atrPeriod;const atr=features[i].atr;if(!atr)continue;const hm=clock(b.end).hm;
let candidate=null;
if(model==='orb'&&!orbUsed&&opening.length===15&&hm>='09:45'&&(b.c>=orHigh+cfg.buffer||b.c<=orLow-cfg.buffer)){orbUsed=true;const side=b.c>=orHigh+cfg.buffer?1:-1;candidate={side,stop:side===1?down(b.c-atr):up(b.c+atr),context:{rangeHigh:orHigh,rangeLow:orLow,atr}};}
const before=bs.slice(Math.max(0,i-cfg.sweepLookback),i),ready=before.length===cfg.sweepLookback,ph=ready?Math.max(...before.map(x=>x.h)):null,pl=ready?Math.min(...before.map(x=>x.l)):null,lowSweep=ready&&b.l<=pl-.25&&b.c>pl&&b.c<ph,highSweep=ready&&b.h>=ph+.25&&b.c<ph&&b.c>pl;
if(model==='liquidity'&&lowSweep!==highSweep&&(lowSweep||highSweep)){const side=lowSweep?1:-1;candidate={side,stop:side===1?down(b.l-cfg.buffer):up(b.h+cfg.buffer),context:{priorHigh:ph,priorLow:pl,sweepExtreme:side===1?b.l:b.h,lookback:cfg.sweepLookback}};}
if(model==='ict'){
 if(sweep&&i-sweep.index>cfg.structureDeadline&&!sweep.shifted)sweep=null;
 if(sweep&&!sweep.shifted&&i>sweep.index){const body=(b.c-b.o)*sweep.side,breaks=sweep.side===1?b.c>sweep.structure:b.c<sweep.structure;if(body>=atr&&breaks){sweep.shifted=true;sweep.shiftIndex=i;sweep.shiftAt=b.end;}}
 if(lowSweep!==highSweep&&(lowSweep||highSweep)){const side=lowSweep?1:-1,st=bs.slice(Math.max(0,i-cfg.structureLookback),i);sweep={index:i,side,extreme:side===1?b.l:b.h,structure:side===1?Math.max(...st.map(x=>x.h)):Math.min(...st.map(x=>x.l)),shifted:false,sweepAt:b.end,priorHigh:ph,priorLow:pl};}
}
if(model==='fvg'||model==='ifvg'||model==='ict'){
 for(let k=gaps.length-1;k>=0;k--){const g=gaps[k],age=i-g.index;if(g.used||age>cfg.gapLifeBars){gaps.splice(k,1);continue;}const inverted=g.side===1?b.c<g.lo:b.c>g.hi;
 if(model==='ifvg'&&inverted){g.used=true;const side=-g.side;candidate={side,stop:side===1?down(Math.min(g.lo,b.l)-cfg.buffer):up(Math.max(g.hi,b.h)+cfg.buffer),context:{gap:{...g},inversionAt:b.end,atr}};break;}
 if(inverted){g.used=true;continue;}if(age>0&&b.h>=g.lo&&b.l<=g.hi&&(b.c-b.o)*g.side>0&&(g.side===1?b.c>=(g.lo+g.hi)/2:b.c<=(g.lo+g.hi)/2)){
 if(model==='ict'&&(!sweep||!sweep.shifted||g.side!==sweep.side||g.index<sweep.shiftIndex||i-sweep.index>cfg.structureDeadline+cfg.gapLifeBars))continue;
 g.used=true;candidate={side:g.side,stop:g.side===1?down((model==='ict'?sweep.extreme:g.lo)-cfg.buffer):up((model==='ict'?sweep.extreme:g.hi)+cfg.buffer),context:{gap:{...g},atr,...(model==='ict'?{sweep:{...sweep}}:{})}};if(model==='ict')sweep=null;break;}
 }
 const a=bs[i-2],middle=bs[i-1];if(a&&b.t-a.t===2*tf*60000){const bull=b.l-a.h>=cfg.minGap,bear=a.l-b.h>=cfg.minGap;if((bull||bear)&&(middle.c-middle.o)*(bull?1:-1)>=.5*(features[i-1]?.atr??atr)){gaps.push({lo:bull?a.h:b.h,hi:bull?b.l:a.l,side:bull?1:-1,index:i,born:b.end,used:false});}}
}
if(model==='hs'&&i>=2*cfg.pivotConfirmBars){const j=i-cfg.pivotConfirmBars,p=bs[j],neighbors=bs.slice(j-cfg.pivotConfirmBars,j+cfg.pivotConfirmBars+1).filter((_,k)=>k!==cfg.pivotConfirmBars),hi=neighbors.every(x=>p.h>x.h),lo=neighbors.every(x=>p.l<x.l);if(hi!==lo&&(hi||lo)){const pivot={kind:hi?'H':'L',price:hi?p.h:p.l,index:j,t:p.t,confirmedAt:b.end};const last=pivots.at(-1);if(last?.kind===pivot.kind){if(pivot.kind==='H'?pivot.price>last.price:pivot.price<last.price)pivots[pivots.length-1]=pivot;}else pivots.push(pivot);if(pivots.length>20)pivots.shift();}
 if(pivots.length>=5){const ps=pivots.slice(-5),[ls,n1,head,n2,rs]=ps,shape=ps.map(p=>p.kind).join(''),top=shape==='HLHLH',bottom=shape==='LHLHL';if((top||bottom)&&rs.index-ls.index<=40&&Math.abs(ls.price-rs.price)<=atr&&(top?head.price>=Math.max(ls.price,rs.price)+.5*atr:head.price<=Math.min(ls.price,rs.price)-.5*atr)){const neck=n1.price+(n2.price-n1.price)*(i-n1.index)/(n2.index-n1.index),key=ps.map(p=>p.index).join('-'),side=top?-1:1;if(!usedPatterns.has(key)&&(side===1?b.c>=neck+.25:b.c<=neck-.25)){usedPatterns.add(key);candidate={side,stop:side===1?down(rs.price-cfg.buffer):up(rs.price+cfg.buffer),context:{pivots:ps.map(p=>({...p})),neckline:neck,atr,pivotConfirmationBars:cfg.pivotConfirmBars}};}}}
}
if(candidate&&hm>='09:30'&&hm<'16:00')push(b,i,candidate);
}
return signals;}
export function executeSetups(minutes,signals,window,cfg=timeConfig){const events=new Map(signals.filter(s=>{const h=clock(s.confirmedAt).hm;return h>=window.start&&h<window.end;}).map(s=>[s.confirmedAt,{...s,context:structuredClone(s.context)}]));const recorded=[...events.values()],trades=[],slip=cfg.slipTicks*.25;let p=null,dayPnl=0,locked=false;
function close(b,exit,reason){const gross=(exit-p.entry)*p.side*2*p.qty,fees=p.qty*cfg.commission,pnl=gross-fees;trades.push({...p,exit,exitTime:b.t,reason,gross,fees,pnl,realizedR:pnl/p.risk});dayPnl+=pnl;if(dayPnl<=-cfg.dailyLoss)locked=true;p=null;}
for(const b of minutes){const hm=clock(b.t).hm,occupiedAtOpen=!!p;if(p){if(hm>='16:00')close(b,tick(b.o-p.side*slip),'Session close');else if(p.side===1?b.l<=p.stop:b.h>=p.stop)close(b,tick((p.side===1?Math.min(b.o,p.stop):Math.max(b.o,p.stop))-p.side*slip),'Stop');else if(p.side===1?b.h>=p.target:b.l<=p.target)close(b,p.target,'Target');}
const s=events.get(b.t);if(!s)continue;s.decisionTime=b.t;if(occupiedAtOpen){s.status='Rejected';s.rejection='Position already open at decision time';continue;}if(locked){s.status='Rejected';s.rejection='Daily loss budget reached';continue;}
const entry=tick(b.o+s.side*slip),distance=(entry-s.stop)*s.side,unitRisk=(distance+slip)*2+cfg.commission,budget=Math.min(cfg.risk,Math.max(0,cfg.dailyLoss+dayPnl)),qty=unitRisk>0?Math.min(cfg.maxContracts,Math.floor(budget/unitRisk)):0,target=tick(entry+s.side*cfg.rr*distance);s.entry=entry;s.target=target;s.qty=qty;s.risk=unitRisk*qty;
if(distance<=0||qty<1){s.status='Rejected';s.rejection=distance<=0?'Stop is on wrong side after the opening gap':'One MNQ exceeds remaining risk budget';continue;}s.status='Simulated';p={...s,entryTime:b.t,plannedR:cfg.rr};if(p.side===1?b.l<=p.stop:b.h>=p.stop)close(b,tick((p.side===1?Math.min(b.o,p.stop):Math.max(b.o,p.stop))-p.side*slip),'Stop');else if(p.side===1?b.h>=p.target:b.l<=p.target)close(b,p.target,'Target');
}
for(const s of recorded)if(s.status==='Detected'){s.status='Rejected';s.rejection='No contiguous minute open at confirmation time';}
if(p){const b=minutes.at(-1);close(b,tick(b.c-p.side*slip),'End of data');}return {trades,signals:recorded};}
function stats(trades){return {...summarize(trades),averageR:trades.length?trades.reduce((s,t)=>s+t.realizedR,0)/trades.length:null};}
function cellStats(cell,days){return stats(cell.trades.filter(t=>days.includes(t.day)));}
export function chooseDevelopment(cells,cfg=timeConfig){const eligible=cells.filter(c=>c.development.trades>=cfg.minimumDevelopmentTrades&&c.development.net>0&&c.development.averageR>0&&c.stressDevelopment.net>0);const sort=(a,b)=>b.development.averageR-a.development.averageR||b.development.net-a.development.net||a.id.localeCompare(b.id);eligible.sort(sort);const families=timeModels.map(m=>({model:m.id,cellId:eligible.filter(c=>c.model===m.id).sort(sort)[0]?.id??null}));return {minimumTrades:cfg.minimumDevelopmentTrades,rule:'At least 10 development trades; positive development net P&L and average realized R; positive development net under doubled costs. Rank by development average realized R, then net P&L, then ID. Never select using check-period results.',eligibleCount:eligible.length,cellId:eligible[0]?.id??null,families};}
export function runTimeStudy(input,cfg=timeConfig){const groups=new Map();for(const b of input){const c=clock(b.t);if(c.hm<'07:00'||c.hm>'16:00')continue;if(!groups.has(c.day))groups.set(c.day,[]);groups.get(c.day).push(b);}const allDays=[...cfg.developmentDays,...cfg.checkDays];for(const day of allDays){const r=(groups.get(day)||[]).filter(b=>clock(b.t).hm>='09:30');if(r.length!==391)throw Error('Incomplete regular session '+day);for(let i=1;i<r.length;i++)if(r[i].t-r[i-1].t!==60000)throw Error('Missing regular-session minute '+day);}
const cells=timeModels.flatMap(m=>cfg.timeframes.flatMap(tf=>cfg.windows.map(w=>({id:`${m.id}-${tf}-${w.id}`,model:m.id,timeframe:tf,window:w.id,windowName:w.name,start:w.start,end:w.end,trades:[],signals:[],stressTrades:[],daily:[]}))));
function phase(days){for(const day of days){const minutes=groups.get(day),signalCache=new Map();for(const m of timeModels)for(const tf of cfg.timeframes)signalCache.set(`${m.id}-${tf}`,detectSetups(minutes,tf,m.id,cfg));for(const cell of cells){const window=cfg.windows.find(w=>w.id===cell.window),signals=signalCache.get(`${cell.model}-${cell.timeframe}`),r=executeSetups(minutes,signals,window,cfg),stress=executeSetups(minutes,signals,window,{...cfg,commission:cfg.commission*2,slipTicks:cfg.slipTicks*2});cell.trades.push(...r.trades);cell.signals.push(...r.signals);cell.stressTrades.push(...stress.trades);cell.daily.push({day,phase:cfg.developmentDays.includes(day)?'development':'check',signals:r.signals.length,...stats(r.trades)});}}}
phase(cfg.developmentDays);for(const c of cells){c.development=cellStats(c,cfg.developmentDays);c.stressDevelopment=stats(c.stressTrades);}const selection=chooseDevelopment(cells,cfg);
phase(cfg.checkDays);for(const c of cells){c.check=cellStats(c,cfg.checkDays);c.fresh=cellStats(c,cfg.freshDays);c.all=stats(c.trades);c.stressCheck=stats(c.stressTrades.filter(t=>cfg.checkDays.includes(t.day)));delete c.stressTrades;}
return {config:cfg,models:timeModels,selection,cells};}
